<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import BaseLayout from '../layout/BaseLayout.vue';
import api from '../../axiosInstance';
import { salesError } from '../../models/sales';
import useUnsavedChanges from '../../models/useUnsavedChanges';
import { confirmDialog } from '../../models/confirmDialog';

const tab = ref('campaigns'), data = ref(null), busy = ref(false), error = ref(''), notice = ref('');
const date = (d) => { const x = new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
const from = ref(date(Date.now()-29*86400000)), to = ref(date(Date.now()));
const blank = () => ({track_clicks:true,track_opens:false,trigger_event:null,delay_hours:24,layout:'default',name:'',subject:'',heading:'',body:'',button_label:'Pozrieť ponuku',button_url:'https://zastavy-vlajky.sk',coupon_id:null});
const form = ref(blank()), editing = ref(false), html = ref(''), schedule = ref(''), confirmSend = ref(false);
const { markAsSaved, isDirty } = useUnsavedChanges(() => form.value);
async function discard() { return !isDirty.value || await confirmDialog({title:'Neuložené zmeny',message:'Zahodiť zmeny v koncepte?',confirmLabel:'Zahodiť'}); }
async function closeEditor() { if(await discard()){editing.value=false;markAsSaved();} }
const contactPage = ref(null), search = ref(''), emails = ref(''), permission = ref(''), confirmed = ref(false), importCustomers = ref(false);
const log = ref(null), logCampaign = ref(null);
const labels = {draft:'Koncept',queued:'Naplánované',completed:'Dokončené',cancelled:'Zastavené',pending:'Čaká',sending:'Odosielanie / overiť',sent:'Odoslané',failed:'Zlyhalo',bounced:'Nedoručiteľné',skipped:'Preskočené'};
const triggerLabel = (v) => data.value?.triggers.find((t) => t.value === v)?.label ?? v;
const triggerShort = (v) => data.value?.triggers.find((t) => t.value === v)?.short ?? v;
const delayLabel = (h) => data.value?.delays.find((d) => d.value === h)?.label ?? `${h} h`;
// Aktuálna hodnota sa ponúka aj vtedy, keď už nie je medzi predvolenými (staršie kampane).
const delayChoices = computed(() => {
 const list = data.value?.delays ?? [];
 return list.some((d) => d.value === form.value.delay_hours) ? list : [...list, {value:form.value.delay_hours,label:`${form.value.delay_hours} h`}];
});
const presets = [
 {"name":"Vlajky a štátne symboly","layout":"flags-catalog","subject":"Vlajky SR a EÚ za 23 € s DPH – ponuka pre školy a obce","heading":"Nová vlajka. Dôstojný prvý dojem.","body":"je čas vymeniť opotrebovanú vlajku alebo doplniť výzdobu vašich priestorov? Pripravili sme pre vás výber z ponuky zástav, vlajok a štátnych symbolov s cenami vrátane DPH.","button_label":"Prezrieť celú ponuku →","button_url":"https://zastavy-vlajky.sk/"},
 {"name":"Spisor.eu – Anonymizer","layout":"spisor","subject":"Citlivé údaje zmiznú. Dokument zostane.","heading":"Citlivé údaje zmiznú. Dokument zostane.","body":"pred odoslaním či zverejnením dokumentu treba myslieť aj na údaje, ktoré nemajú vidieť ostatní. Anonymizer vám ich pomôže nájsť a natrvalo odstrániť.\n\nAutomaticky rozpozná mená, rodné čísla, IBAN, e-maily a ďalšie citlivé údaje. Vy skontrolujete nálezy a rozhodnete, čo sa má začierniť.","button_label":"Vyskúšať Anonymizer →","button_url":"https://spisor.eu"},
 {name:'Sezónna ponuka',subject:'Pripravte sa na novú sezónu s nami',heading:'Nová sezóna. Nové farby.',body:'Doplňte svoju výbavu o kvalitné zástavy a vlajky. Radi vám pomôžeme vybrať vhodné rozmery aj materiál.\n\nPozrite si našu ponuku alebo nám odpovedzte na tento email – pripravíme vám riešenie na mieru.'},
 {name:'Poďakovanie s kupónom',subject:'Malé poďakovanie za vašu dôveru',heading:'Ďakujeme, že ste s nami.',body:'Vážime si našu spoluprácu. Ako poďakovanie sme pre vás pripravili zľavový kupón na ďalší nákup.\n\nKód stačí zadať v košíku. Tešíme sa na vašu ďalšiu objednávku.'},
 {name:'Výroba na mieru',subject:'Vaša značka si zaslúži byť viditeľná',heading:'Vlajka presne podľa vás.',body:'Chystáte podujatie alebo chcete zviditeľniť svoju firmu? Vyrobíme vám vlajky a zástavy s vlastnou potlačou.\n\nNapíšte nám svoju predstavu. Pomôžeme s grafikou, materiálom aj výberom správneho uchytenia.'},
];
const templateList = computed(() => [...presets, ...(data.value?.templates || [])]);
const templatePreviews = ref({});
const templateKey = t => `${t.layout || 'default'}:${t.id || t.name}`;
let previewRevision = 0;
watch([tab, templateList], async ([currentTab, templates]) => {
 if(currentTab !== 'templates') return;
 const revision = ++previewRevision;
 const results = await Promise.allSettled(templates.map(async t => {
  const response = await api.post('/emailing/preview', {...blank(), ...t, coupon_id:null});
  return [templateKey(t), response.data.html];
 }));
 if(revision !== previewRevision) return;
 templatePreviews.value = Object.fromEntries(results.filter(r => r.status === 'fulfilled').map(r => r.value));
});
const chart = computed(() => {
 const rows = []; const start = new Date(from.value+'T12:00:00'), end = new Date(to.value+'T12:00:00');
 for (let d = start; d <= end && rows.length < 366; d.setDate(d.getDate()+1)) {
  const day = date(d); rows.push({day,total:Number(data.value?.stats.daily.find(x=>x.day===day)?.total || 0)});
 }
 return rows;
});
const maximum = computed(()=>Math.max(1,...chart.value.map(x=>x.total)));
async function act(fn) { if(busy.value)return; busy.value=true;error.value='';notice.value=''; try { await fn(); } catch(e) { error.value=salesError(e); } finally { busy.value=false; } }
async function load(page=1) { data.value=(await api.get('/emailing',{params:{from:from.value,to:to.value,page}})).data; }
async function contacts(page=1) { contactPage.value=(await api.get('/emailing/contacts',{params:{search:search.value,page}})).data; }
async function compose(source=null) { if(editing.value && !(await discard())) return; form.value=source ? {...blank(),...source,track_clicks:Boolean(source.track_clicks ?? true),track_opens:Boolean(source.track_opens)} : blank();editing.value=true;html.value='';confirmSend.value=false;schedule.value='';tab.value='campaigns';markAsSaved(); }
function useTemplate(t) { compose({...blank(),...t,id:undefined,coupon_id:null}); }
async function preview() { html.value=(await api.post('/emailing/preview',form.value)).data.html; }
async function save() { const r=form.value.id ? await api.put(`/emailing/campaigns/${form.value.id}`,form.value) : await api.post('/emailing/campaigns',form.value);form.value=r.data;markAsSaved();await load();notice.value='Koncept je uložený.'; }
async function queue() { await save(); await api.post(`/emailing/campaigns/${form.value.id}/queue`,{scheduled_at:!form.value.trigger_event && schedule.value ? new Date(schedule.value).toISOString() : null});editing.value=false;confirmSend.value=false;await load();notice.value=form.value.trigger_event ? 'Automatizácia je aktívna pre nové udalosti.' : 'Kampaň je zaradená na odoslanie.'; }
async function showLog(c,page=1) {logCampaign.value=c;log.value=(await api.get(`/emailing/campaigns/${c.id}/deliveries`,{params:{page}})).data;}
async function addContacts() {const r=await api.post('/emailing/contacts',{emails:emails.value,permission_note:permission.value,confirmed:confirmed.value,import_customers:importCustomers.value});notice.value=`Pridané: ${r.data.added}. Duplicity, odhlásené alebo neplatné adresy: ${r.data.skipped}.`;emails.value='';confirmed.value=false;importCustomers.value=false;await contacts();await load();}
const time = x => x ? new Date(x.includes('T') ? x : x.replace(' ','T')).toLocaleString('sk-SK') : '—';
onMounted(()=>act(()=>load()));
</script>

<template>
<BaseLayout><template #main><div class="mailing page-body col-span-12">
 <header class="hero"><div><div class="eyebrow">BLIŽŠIE K VAŠIM ZÁKAZNÍKOM</div><h1>Emailing</h1><p>Ponuky, ktoré potešia. Kampane, v ktorých máte poriadok.</p></div><button class="white" @click="compose()">＋ Nová kampaň</button></header>
 <div v-if="error" role="alert" class="alert error">{{ error }}</div><div v-if="notice" role="status" class="alert success">{{ notice }}</div>
 <div v-if="data?.dry_run" class="alert setup"><strong>Testovací režim.</strong> Kampane prebiehajú ako naostro (fronta, oneskorenie, záznamy ako „Odoslané“), ale žiadny email sa reálne neodosiela.</div>
 <div v-if="data && !data.ready" class="alert setup"><strong>Pripravte si prvú kampaň.</strong> Odosielanie zatiaľ nie je zapnuté. Pred spustením musí správca pripojiť poštový server a zapnúť automatické odosielanie.</div>
 <div class="toolbar"><nav aria-label="Emailing"><button v-for="[key,label] in [['campaigns','Kampane'],['templates','Šablóny'],['contacts','Príjemcovia'],['stats','Štatistiky']]" :key="key" :class="{selected:tab===key}" @click="tab=key; key==='contacts' && act(()=>contacts())">{{ label }}</button></nav><span v-if="data" class="muted">Limit {{ data.hourly_limit }} emailov / hodinu</span></div>
 <template v-if="data">
 <div class="metrics"><article><span>Odoslané v období</span><strong>{{ data.stats.sent }}</strong><small>{{ from }} – {{ to }}</small></article><article><span>Aktívni príjemcovia</span><strong>{{ data.stats.active }}</strong><small>Jedna adresa, jeden email</small></article><article><span>Čakajú na odoslanie</span><strong>{{ data.stats.pending }}</strong><small>Postupne po dávkach</small></article><article><span>Odhlásené adresy</span><strong>{{ data.stats.unsubscribed }}</strong><small>Vylúčené z ďalších kampaní</small></article><article><span>Nedoručiteľné adresy</span><strong>{{ data.stats.bounced }}</strong><small>Automaticky vylúčené</small></article></div>
 <section v-if="tab==='campaigns' && !editing" class="panel"><div class="section-title"><div><h2>Vaše kampane</h2><p>Od prvého nápadu po posledný odoslaný email.</p></div><button :disabled="busy" @click="act(()=>load())">Obnoviť</button></div>
 <div v-if="!data.campaigns.data.length" class="empty"><div class="empty-icon">✉</div><h2>Prvá ponuka začína tu</h2><p>Vyberte šablónu, napíšte pár slov a potešte svojich zákazníkov.</p><button class="primary" @click="tab='templates'">Vybrať šablónu</button></div>
 <div v-else class="table-wrap"><table><thead><tr><th>Kampaň</th><th>Stav</th><th>Plánovaný začiatok ({{data.timezone}})</th><th>Akcie</th></tr></thead><tbody><tr v-for="c in data.campaigns.data" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.subject}}</small></td><td><span class="badge" :class="c.status">{{labels[c.status]}}</span></td><td>{{c.trigger_event ? `${triggerShort(c.trigger_event)} · ${delayLabel(c.delay_hours)}` : time(c.scheduled_at)}}</td><td class="actions"><button v-if="c.status==='draft'" @click="compose(c)">Upraviť</button><button @click="act(()=>showLog(c))">Záznamy</button><button @click="compose({...c,id:undefined,status:'draft',name:c.name+' – kópia'})">Kopírovať</button><button v-if="c.status==='queued'" :disabled="busy" @click="act(async()=>{await api.post(`/emailing/campaigns/${c.id}/cancel`);await load();notice='Kampaň bola zastavená. Práve odosielaný email sa môže dokončiť.'})">Zastaviť</button></td></tr></tbody></table></div>
 <div class="pager"><button :disabled="busy || data.campaigns.current_page<=1" @click="act(()=>load(data.campaigns.current_page-1))">Späť</button><span>{{data.campaigns.current_page}} / {{data.campaigns.last_page}}</span><button :disabled="busy || data.campaigns.current_page>=data.campaigns.last_page" @click="act(()=>load(data.campaigns.current_page+1))">Ďalej</button></div></section>
 <section v-if="tab==='campaigns' && editing" class="editor">
 <form class="panel" @submit.prevent="act(save)"><div class="section-title"><h2>{{form.id ? 'Upraviť koncept' : 'Nová kampaň'}}</h2><button type="button" @click="closeEditor()">Zavrieť</button></div>
 <p v-if="form.layout==='spisor'" class="muted">Šablóna Spisor.eu zachováva značku, úvod a informačné bloky. Nižšie upravíte nadpis, hlavný text a tlačidlo.</p><p v-if="form.layout==='flags-catalog'" class="muted">Katalóg zachováva štyri produkty, obrázky, ceny a kontakty z dodanej šablóny. Nižšie upravíte predmet, nadpis, úvodný text a hlavné tlačidlo.</p><label>Interný názov kampane<input v-model="form.name" required maxlength="255" placeholder="Napr. Jesenná ponuka 2026"></label><label>Predmet emailu<input v-model="form.subject" required maxlength="200" placeholder="Čo zákazník uvidí v schránke"></label><label>Nadpis ponuky<input v-model="form.heading" required maxlength="200" placeholder="Dajte svojej značke farby."></label><label>Text ponuky<textarea v-model="form.body" required rows="8" maxlength="20000" placeholder="Napíšte ponuku vlastnými slovami…"></textarea></label>
 <div class="two"><label>Text tlačidla<input v-model="form.button_label" maxlength="80"></label><label>Odkaz tlačidla<input v-model="form.button_url" type="url" placeholder="https://"></label></div><label>Zľavový kupón<select v-model="form.coupon_id"><option :value="null">Bez kupóna</option><option v-for="c in data.coupons" :key="c.id" :value="c.id">{{c.code}} · {{c.value}}{{c.type==='percent'?' %':' €'}} · do {{c.valid_to || 'neobmedzene'}}</option></select></label><p class="muted">Kupóny vytvoríte v <RouterLink :to="{name:'coupons.index'}">správe kupónov</RouterLink>. Pred odoslaním skontrolujte ich podmienky a platnosť.</p>
 <div class="actions"><button class="primary" :disabled="busy">Uložiť koncept</button><button type="button" :disabled="busy" @click="act(preview)">Zobraziť náhľad</button><button type="button" :disabled="busy" @click="act(async()=>{await api.post('/emailing/templates',form);await load();notice='Šablóna je uložená.'})">Uložiť ako šablónu</button></div>
 <div class="send-box"><h3>Meranie odozvy</h3><label class="check"><input type="checkbox" v-model="form.track_clicks"> Merať návštevy tlačidiel a produktových odkazov</label><label class="check"><input type="checkbox" v-model="form.track_opens"> Odhadovať otvorenia pomocou obrázka (voliteľné)</label><p class="muted">Vlastné HTTPS odkazy, bez externého trackera a analytických cookies. Načítanie obrázka nepotvrdzuje prečítanie. Poštové proxy a bezpečnostné skenery môžu skresliť oba údaje; známe roboty filtrujeme. Odhlásenie a odkazy zobrazené ako webová adresa zostávajú priame. Meranie prebieha 90 dní od pokusu o odoslanie; odkazy fungujú aj potom.</p><label>Spôsob spustenia<select v-model="form.trigger_event"><option :value="null">Jednorazová kampaň</option><option v-for="t in data.triggers" :key="t.value" :value="t.value">{{t.label}}</option></select></label><label v-if="form.trigger_event">Oneskorenie odoslania<select v-model.number="form.delay_hours" required><option v-for="d in delayChoices" :key="d.value" :value="d.value">{{d.label}}</option></select></label><p v-if="form.trigger_event" class="muted">Email sa odošle až po zvolenom oneskorení od udalosti. Platí pre nové udalosti po aktivácii a iba pre aktívne kontakty v Príjemcoch. Každá objednávka (pri expedícii každá zásielka) spustí jednu ponuku. Stornované alebo odstránené objednávky sa preskočia.</p><h3>Pripravené na cestu?</h3><p>{{data.stats.active}} aktívnych príjemcov · najviac {{data.hourly_limit}} emailov za hodinu.</p><label v-if="!form.trigger_event">Naplánovať začiatok (váš miestny čas)<input type="datetime-local" v-model="schedule"></label><small v-if="!form.trigger_event">Prázdny dátum = najbližší beh plánovača.</small><div class="actions"><button type="button" :disabled="busy || !data.ready" @click="act(async()=>{const r=await api.post('/emailing/test',form);notice=r.data.message})">Poslať test sebe</button><button type="button" class="primary" :disabled="busy || !data.ready || (!form.trigger_event && !data.stats.active)" @click="confirmSend=true">{{form.trigger_event ? 'Aktivovať automatizáciu' : 'Pripraviť odoslanie'}}</button></div>
 <div v-if="confirmSend" class="confirm"><strong>{{form.trigger_event ? `Aktivovať ponuku s oneskorením ${delayLabel(form.delay_hours)}: ${triggerLabel(form.trigger_event).toLowerCase()}?` : `Odoslať túto ponuku všetkým ${data.stats.active} aktívnym príjemcom?`}}</strong><p>Po zaradení sa obsah uzamkne. Neodoslané emaily môžete zastaviť v zozname kampaní.</p><button type="button" class="primary" :disabled="busy" @click="act(queue)">Potvrdiť a zaradiť</button> <button type="button" @click="confirmSend=false">Späť</button></div></div>
 </form><aside class="preview panel"><div class="section-title"><h2>Náhľad emailu</h2><span class="badge">Mobil aj počítač</span></div><iframe v-if="html" :srcdoc="html" sandbox="" title="Náhľad emailovej ponuky"></iframe><div v-else class="empty"><div class="empty-icon">✉</div><p>Vyplňte ponuku a kliknite na „Zobraziť náhľad“.</p><small>Po úpravách náhľad obnovte.</small></div></aside>
 </section>
 <section v-if="tab==='templates'"><div class="section-title"><div><h2>Dobrá ponuka má dobrý začiatok</h2><p>Vyberte základ a upravte ho podľa seba.</p></div></div><div class="templates"><article v-for="(t,i) in templateList" :key="templateKey(t)" class="panel template"><iframe v-if="templatePreviews[templateKey(t)]" class="template-preview" :srcdoc="templatePreviews[templateKey(t)]" sandbox="" :title="'Náhľad šablóny: '+t.name" loading="lazy"></iframe><div v-else class="sample" :class="t.layout==='spisor' ? 'sample-spisor' : t.layout==='flags-catalog' ? 'sample-catalog' : 'sample-'+i%3"><div>{{t.layout==='spisor' ? 'SPISOR.EU' : 'ZÁSTAVY & VLAJKY'}}</div><h3>{{t.heading}}</h3><span>{{t.button_label || 'POZRIEŤ PONUKU →'}}</span></div><h3>{{t.name}}</h3><p>{{t.subject}}</p><button @click="useTemplate(t)">Použiť šablónu →</button></article></div></section>
 <section v-if="tab==='contacts'" class="contacts-layout"><form class="panel" @submit.prevent="act(addContacts)"><h2>Pridať príjemcov</h2><p>Vložte adresy oddelené čiarkou, bodkočiarkou alebo novým riadkom.</p><label>Emailové adresy<textarea v-model="emails" rows="6" placeholder="zakaznik@firma.sk"></textarea></label><label class="check"><input type="checkbox" v-model="importCustomers"> Importovať aj kontakty existujúcich zákazníkov</label><label>Zdroj a oprávnenie na zasielanie<input v-model="permission" required minlength="5" maxlength="255" placeholder="Napr. súhlas z formulára, dátum a zdroj"></label><label class="check"><input type="checkbox" v-model="confirmed" required> Potvrdzujem oprávnenie posielať ponuky týmto kontaktom.</label><p class="muted">Samotná existencia zákazníka nie je záznam súhlasu. Importujte len kontakty, ktorým môžete ponuky zasielať. Odhlásenie sa importom nikdy nezruší.</p><button class="primary" :disabled="busy || (!emails.trim() && !importCustomers)">Pridať kontakty</button></form>
 <div class="panel"><div class="section-title"><h2>Adresár príjemcov</h2></div><form class="search" @submit.prevent="act(()=>contacts())"><input v-model="search" placeholder="Hľadať email" aria-label="Hľadať email"><button :disabled="busy">Hľadať</button></form><div class="table-wrap"><table><thead><tr><th>Kontakt / zdroj</th><th>Stav</th><th></th></tr></thead><tbody><tr v-for="c in contactPage?.data || []" :key="c.id"><td>{{c.email}}<small>{{c.name}} · {{c.permission_note}}</small></td><td><span class="badge" :class="c.unsubscribed_at||c.bounced_at?'cancelled':'completed'">{{c.unsubscribed_at?'Odhlásený':c.bounced_at?(c.bounce_type==='hard'?'Neexistuje':'Opakovane nedoručené'):'Aktívny'}}</span><small v-if="c.bounced_at && !c.unsubscribed_at">{{c.bounce_reason}}</small></td><td><button v-if="!c.unsubscribed_at" :disabled="busy" @click="act(async()=>{await api.post(`/emailing/contacts/${c.id}/suppress`);await contacts();await load()})">Odhlásiť</button><button v-if="c.bounced_at && !c.unsubscribed_at" :disabled="busy" @click="act(async()=>{await api.post(`/emailing/contacts/${c.id}/reactivate`);await contacts();await load()})">Obnoviť</button></td></tr></tbody></table></div><p v-if="!contactPage?.data.length" class="empty">Zatiaľ žiadni príjemcovia.</p><div v-if="contactPage" class="pager"><button :disabled="busy || contactPage.current_page<=1" @click="act(()=>contacts(contactPage.current_page-1))">Späť</button><span>{{contactPage.current_page}} / {{contactPage.last_page}}</span><button :disabled="busy || contactPage.current_page>=contactPage.last_page" @click="act(()=>contacts(contactPage.current_page+1))">Ďalej</button></div></div></section>
 <section v-if="tab==='stats'" class="panel"><div class="section-title"><div><h2>Ako sa darí odosielaniu</h2><p>Počty emailov prevzatých poštovým serverom.</p><p>Správy s návštevou odkazu: <strong>{{data.stats.clicked}}</strong> · s načítaním meracieho obrázka: <strong>{{data.stats.opened}}</strong></p><small>Odozva na správy odoslané vo vybranom období. Ide o orientačné údaje, nie dôkaz ľudského kliknutia či prečítania. Staršie a nemerané kampane údaje nemajú.</small></div><form class="actions" @submit.prevent="act(()=>load())"><label>Od<input v-model="from" type="date" required></label><label>Do<input v-model="to" type="date" :min="from" required></label><button :disabled="busy">Zobraziť</button></form></div><div v-if="data.stats.sent" class="chart" role="img" :aria-label="`${data.stats.sent} odoslaných emailov vo vybranom období`"><div v-for="d in chart" :key="d.day" class="bar-column" :title="`${d.day}: ${d.total} emailov`"><div class="bar" :style="{height:Math.max(2,d.total/maximum*180)+'px'}"></div></div></div><div v-else class="empty"><h3>V tomto období sa ešte neposielalo</h3><p>Po spustení kampane tu uvidíte denné počty.</p></div><div class="section-title"><small>{{from}}</small><small>{{to}}</small></div><p class="muted">Zlyhané pokusy v období: {{data.stats.failed}}. Odoslanie nepotvrdzuje doručenie ani otvorenie. Graf zobrazuje najviac prvých 366 dní, celkový počet zahŕňa celé obdobie.</p></section>
 </template>
 <p v-else class="empty">{{busy ? 'Načítavam emailing…' : 'Údaje sa nepodarilo načítať.'}} <button v-if="!busy" @click="act(()=>load())">Skúsiť znova</button></p>
 <div v-if="log" class="modal" @click.self="log=null"><section class="panel log" role="dialog" aria-modal="true" aria-label="Záznamy odosielania"><div class="section-title"><div><h2>{{logCampaign.name}}</h2><p>Záznamy odosielania</p><p>Správy s návštevou odkazu: <strong>{{log.engagement.clicked}}</strong> · s načítaním obrázka: <strong>{{log.engagement.opened}}</strong></p><small>Jedna správa sa v súhrne počíta raz. Otvorenia a návštevy môžu zahŕňať automatické kontroly klientov.</small></div><button @click="log=null">Zavrieť</button></div><div class="actions"><span v-for="(total,status) in log.counts" :key="status" class="badge">{{labels[status]}}: {{total}}</span><button :disabled="busy" @click="act(()=>showLog(logCampaign,log.deliveries.current_page))">Obnoviť</button></div><div class="table-wrap"><table><thead><tr><th>Email</th><th>Stav</th><th>Čas ({{data?.timezone}})</th><th>Odozva (orientačná)</th></tr></thead><tbody><tr v-for="d in log.deliveries.data" :key="d.id"><td>{{d.email}}<small v-if="d.event_order_id">Objednávka #{{d.event_order_id}} · plán {{time(d.due_at)}}</small><small v-if="d.error">{{d.error}}</small></td><td>{{labels[d.status]}}</td><td>{{time(d.sent_at || d.attempted_at)}}</td><td><small>Návšteva: {{time(d.clicked_at)}}</small><small>Obrázok: {{time(d.opened_at)}}</small></td></tr></tbody></table></div><div v-if="log.links.length" class="table-wrap"><h3>Odkazy a produkty</h3><table><thead><tr><th>Cieľ odkazu</th><th>Návštevy</th><th>Správy s návštevou</th></tr></thead><tbody><tr v-for="link in log.links" :key="link.url"><td style="overflow-wrap:anywhere">{{link.url}}</td><td>{{link.clicks}}</td><td>{{link.messages}}</td></tr></tbody></table><p class="muted">Obrázok aj tlačidlo rovnakého produktu sa spočítajú podľa cieľovej adresy. Návštevy sú požiadavky po odfiltrovaní známych robotov.</p></div><p v-if="!log.deliveries.data.length" class="empty">Kampaň zatiaľ nemá záznamy odosielania.</p><p class="muted">Dlhšie trvajúci stav „Odosielanie / overiť“ môže znamenať prerušený pokus. Pred ďalším odoslaním overte záznamy poskytovateľa pošty.</p><div class="pager"><button :disabled="busy || log.deliveries.current_page<=1" @click="act(()=>showLog(logCampaign,log.deliveries.current_page-1))">Späť</button><span>{{log.deliveries.current_page}} / {{log.deliveries.last_page}}</span><button :disabled="busy || log.deliveries.current_page>=log.deliveries.last_page" @click="act(()=>showLog(logCampaign,log.deliveries.current_page+1))">Ďalej</button></div></section></div>
</div></template></BaseLayout>
</template>

